#pragma once
/* config_line.c -- the print-only "effective configuration" line (L5, step P1-1 of the parameter system).
 * cfg_snapshot(): at the very top of main, before ecalc sets any variable itself, record which registered switches
 *   (switches_gen.h, generated by tools/switch_registry.py) are set in the environment.
 * cfg_print(eff): print  config: hash=<8 hex> set=<k=v ...> eff=<resolved values>   (rank 0 only; no effect on any result).
 * hash = FNV-1a 32 over the sorted "k=v\n" lines of the set switches. */
void cfg_snapshot(void);
void cfg_print(const char *eff);
